export function CardDataFromTuple(abiTuple: [string, string, bigint, bigint]) {
  return getABIStructFromABITuple(abiTuple, APP_SPEC.structs.CardData, APP_SPEC.structs) as CardData
}

export type Treasury = {
  address: string,
  nonce: bigint
}


